        $pct = $delta / $processSeconds / [double]$logicalCount * 100.0
        if ($pct -gt 2.0) { $heavy += [pscustomobject]@{ ProcessId=$id; Name=$proc1[$id].Name; CpuPercentTotal=$pct } }
    }
}
$chromeAfter = @(Get-Process chrome -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Id)
$meanCpu = ($cpu | Measure-Object -Property PercentProcessorTime -Average).Average
$maxCpu = ($cpu | Measure-Object -Property PercentProcessorTime -Maximum).Maximum
[ordered]@{ captured_utc=(Get-Date).ToUniversalTime().ToString('o'); power_plan_guid=$powerGuid; expected_power_plan_guid=$expectedPower; cpu_names=$cpuInfo; logical_processor_count=$logicalCount; expected_cpu_name='13th Gen Intel(R) Core(TM) i7-13700F'; chrome_pids_before=$chromeBefore; chrome_pids_after=$chromeAfter; cpu_samples=$cpu; mean_cpu_percent=$meanCpu; max_cpu_percent=$maxCpu; heavy_processes_over_2pct_total=$heavy; process_sample_seconds=$processSeconds; cpu_sample_interval_seconds=1; cpu_sample_count=$cpu.Count } | ConvertTo-Json -Depth 6 -Compress
